namespace Puck.Shaders.Study;

/// <summary>
/// The flat-grey compute kernel <see cref="StudyPassNode"/> dispatches before its first successful
/// <see cref="StudyPassNode.Swap(StudyProgram)"/> — writes <c>float4(0.18, 0.18, 0.18, 1.0)</c> to the one storage
/// image at binding 0, reads no push constants, 8×8 workgroups (the same pipeline layout a swapped-in study program
/// builds) — compiled once with <c>dxc</c> (<c>-T cs_6_6</c>, DXIL and <c>-spirv</c>) from
/// <c>study-placeholder.comp.hlsl</c> and embedded so the node never depends on the study toolchain to render its own
/// idle state.
/// </summary>
internal static class StudyPlaceholderShader {
    private const string DxilBase64 =
        "";
    private const string SpirVBase64 =
        "";

    private static readonly ReadOnlyMemory<byte> Dxil = Convert.FromBase64String(DxilBase64);
    private static readonly ReadOnlyMemory<byte> SpirV = Convert.FromBase64String(SpirVBase64);

    /// <summary>Returns the placeholder kernel bytecode for the given host backend.</summary>
    /// <param name="hostsOnDirectX">Whether the resolved host backend is Direct3D 12.</param>
    public static ReadOnlyMemory<byte> Kernel(bool hostsOnDirectX) => (hostsOnDirectX ? Dxil : SpirV);
}
